package co.nexus.research;
import android.app.Activity;import android.os.*;import android.widget.*;import android.graphics.*;import android.view.View;import android.util.AtomicFile;import java.io.*;import java.util.Locale;import java.util.concurrent.*;
public final class SparseActivity extends Activity {
 final Handler ui=new Handler(Looper.getMainLooper());final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();volatile boolean running,training;volatile long generation;SparseBrain core;CognitiveArena arena;AtomicFile checkpoint;TextView status;Board board;String loadNote=""; volatile boolean studying;long evaluationEpisodes,evaluationWins;
 @Override public void onCreate(Bundle b){super.onCreate(b);checkpoint=new AtomicFile(new File(getFilesDir(),"nx15.bin"));LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,24,16,16);status=new TextView(this);status.setTextSize(16);status.setText("Inicializando NEXUS 0.16…");ScrollView details=new ScrollView(this);details.addView(status);root.addView(details,new LinearLayout.LayoutParams(-1,0,1));board=new Board();root.addView(board,new LinearLayout.LayoutParams(-1,0,1));ScrollView controls=new ScrollView(this);LinearLayout buttons=new LinearLayout(this);buttons.setOrientation(1);controls.addView(buttons);root.addView(controls,new LinearLayout.LayoutParams(-1,0,1));button(buttons,"Aprender sin ejemplos",()->start(true));button(buttons,"Evaluar sin aprender",()->start(false));button(buttons,"Video en segundo plano",()->pickVideo());button(buttons,"Informe y errores del video",()->reviewVideo());button(buttons,"Aprender demostración",()->pickDemo());button(buttons,"Aprender demo detectada",()->detectedDemo());button(buttons,"Proponer estrategia",()->showPlan());button(buttons,"Exportar demostración",()->exportDemo());button(buttons,"Abrir laboratorio 0.14",()->{stop();startActivity(new android.content.Intent(this,CognitiveActivity.class));});button(buttons,"Detener y guardar",()->stop());setContentView(root);worker.execute(()->{try(InputStream in=checkpoint.openRead()){core=SparseBrain.read(in);loadNote="Modelo recuperado";}catch(IOException ex){core=new SparseBrain(15);loadNote="Modelo inicial";}try{core.enableDiskCache(new File(getCacheDir(),"experts-"+java.util.UUID.randomUUID()),32);}catch(IOException e){loadNote+=" | caché no disponible";}arena=new CognitiveArena(14);render(null);});}
 void button(LinearLayout root,String text,Runnable r){Button b=new Button(this);b.setText(text);b.setOnClickListener(v->r.run());root.addView(b);}
 void start(boolean train){studying=false;long id=++generation;running=true;training=train;worker.execute(()->{if(generation!=id)return;arena=new CognitiveArena((train?core.episodes:evaluationEpisodes)+(train?1400:90000));tick(id,train);});}
 void tick(long id,boolean train){if(!running||generation!=id||core==null)return;PowerManager pm=getSystemService(PowerManager.class);if(Build.VERSION.SDK_INT>=29&&pm.getCurrentThermalStatus()>=PowerManager.THERMAL_STATUS_SEVERE){running=false;save();loadNote="Pausa térmica";render(null);return;}if(arena.done)arena=new CognitiveArena((train?core.episodes:evaluationEpisodes)+(train?1400:90000));CognitiveCore.Observation o=arena.observe();SparseBrain.Decision d=StrategyLab.choose(core,arena,train);float[] outcome=arena.step(d.action);if(train)core.learn(o,d.action,SparseBrain.outcome(outcome,arena));if(arena.done){if(train){core.episodes++;if(arena.won)core.wins++;if(core.episodes%10==0)save();}else{evaluationEpisodes++;if(arena.won)evaluationWins++;}}render(d);if(running&&generation==id)worker.schedule(()->tick(id,train),train?180:350,TimeUnit.MILLISECONDS);}
 void stop(){studying=false;running=false;generation++;if(!worker.isShutdown())worker.execute(()->{if(core!=null){save();render(null);}});}
 void save(){FileOutputStream out=null;try{out=checkpoint.startWrite();core.write(out);checkpoint.finishWrite(out);loadNote="Checkpoint guardado";}catch(IOException ex){if(out!=null)checkpoint.failWrite(out);loadNote="Error guardando checkpoint";}}
 void render(SparseBrain.Decision d){String t="NEXUS 0.16 · Laboratorio neuronal\n412 redes · 8 × 1024 → 16 · 80 roles | "+(studying?"Video":running?(training?"Aprendizaje":"Evaluación"):"Detenido")+"\nEpisodios: "+core.episodes+" | Éxitos: "+core.wins+" | Actualizaciones: "+core.updates+"\nEvaluación: "+evaluationWins+"/"+evaluationEpisodes+"\nRedes entrenadas: "+core.trained()+"/412 | residentes "+core.allocated()+" | pares de video: "+getSharedPreferences("video16",MODE_PRIVATE).getLong("pairs",0)+"\nSalud: "+arena.health+" | Energía: "+arena.energy+" | Kits: "+arena.kits+"\n"+arena.event+"\n"+(arena.steps==0?"":"NXD "+arena.seed+" "+arena.steps+" "+arena.history().get(arena.steps-1).name()+"\n")+(d==null?"":String.format(Locale.ROOT,"U %.2f | S %.2f | C %.2f | I %.2f | Incert. %.2f\n",d.heads[0],d.heads[1],d.heads[2],d.heads[3],d.uncertainty))+(d==null?"":"Agente "+(d.agent+1)+" / 80\n"+allHeads(d.heads)+"\n")+loadNote;int[] cells={arena.pos,arena.goal,arena.resource,arena.kit,arena.mount,arena.beacon};ui.post(()->{if(isDestroyed())return;status.setText(t);board.cells=cells;board.invalidate();});}
 void pickVideo(){stop();android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);i.setType("video/*");i.addCategory(android.content.Intent.CATEGORY_OPENABLE);startActivityForResult(i,15);}
 @Override protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;final android.net.Uri uri=data.getData();if(request==15){try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}try{startForegroundService(new android.content.Intent(this,VideoAuditService.class).setData(uri).addFlags(android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION));loadNote="Video iniciado; consulta Informe y errores";}catch(RuntimeException e){loadNote="No se inició video: "+e.getMessage();}return;}if(request==16){stop();worker.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Archivo no disponible");trainDemo(in);}catch(IOException e){loadNote=e.getMessage();render(null);}});}if(request==17){stop();worker.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Archivo no disponible");StrategyLab.exportDemo(out,arena);loadNote="Demostración exportada";}catch(IOException e){loadNote=e.getMessage();}render(null);});}}
 void pickDemo(){stop();android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);i.setType("text/plain");i.addCategory(android.content.Intent.CATEGORY_OPENABLE);startActivityForResult(i,16);}
 void exportDemo(){stop();android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_CREATE_DOCUMENT);i.setType("text/plain");i.putExtra(android.content.Intent.EXTRA_TITLE,"nexus-demo.txt");i.addCategory(android.content.Intent.CATEGORY_OPENABLE);startActivityForResult(i,17);}
 void trainDemo(InputStream in)throws IOException{StrategyLab.Review r=StrategyLab.importDemo(in,core,true);save();loadNote=r.toString()+" | aprendizaje guardado";render(null);}
 void detectedDemo(){stop();worker.execute(()->{try{String d=VideoAuditService.readText(this,"video16-demo.txt");if(d.isEmpty())throw new IOException("No existe demo local completa en el video");trainDemo(new ByteArrayInputStream(d.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(IOException e){loadNote=e.getMessage();render(null);}});}
 void reviewVideo(){String status=getSharedPreferences("video16",MODE_PRIVATE).getString("status","No hay análisis");String text;try{text=VideoAuditService.readText(this,"video16-report.txt");}catch(IOException e){text="Aún no hay informe";}TextView v=new TextView(this);v.setText(status+"\n\n"+text);v.setTextIsSelectable(true);v.setPadding(24,16,24,16);ScrollView sc=new ScrollView(this);sc.addView(v);new android.app.AlertDialog.Builder(this).setTitle("Revisión de video").setView(sc).setPositiveButton("Cerrar",null).setNeutralButton("Detener video",(d,w)->startService(new android.content.Intent(this,VideoAuditService.class).setAction(VideoAuditService.STOP))).show();}
 void showPlan(){stop();worker.execute(()->{if(arena.done){loadNote="Inicia un episodio para planificar";}else{StrategyLab.Plan p=StrategyLab.propose(arena);loadNote="Secuencia propuesta: "+p.sequence+" | valor "+String.format(Locale.ROOT,"%.3f",p.value);}render(null);});}
 boolean hot(){PowerManager pm=getSystemService(PowerManager.class);return Build.VERSION.SDK_INT>=29&&pm.getCurrentThermalStatus()>=PowerManager.THERMAL_STATUS_SEVERE;}
 String allHeads(float[] h){StringBuilder b=new StringBuilder();for(int j=4;j<h.length;j++){if(j>4)b.append(" · ");b.append(SparseBrain.HEAD_NAMES[j]).append(' ').append(String.format(Locale.ROOT,"%.2f",h[j]));}return b.toString();}
 @Override protected void onPause(){stop();super.onPause();}@Override protected void onDestroy(){running=false;generation++;worker.shutdown();super.onDestroy();}
 final class Board extends View{final Paint p=new Paint();int[] cells={0,63,7,12,21,35};Board(){super(SparseActivity.this);}protected void onDraw(Canvas c){float d=Math.min(getWidth(),getHeight())/8f;p.setTextSize(d*.35f);String[] names={"A","G","E","K","V","B"};int[] colors={0xff22ddcc,0xff55cc77,0xffe4af45,0xffe77f8c,0xff6f9aee,0xffa88bea};for(int i=0;i<64;i++){float x=i%8*d,y=i/8*d;p.setColor(0xff223344);c.drawRect(x+1,y+1,x+d-1,y+d-1,p);for(int j=5;j>=0;j--)if(cells[j]==i){p.setColor(colors[j]);c.drawRect(x+3,y+3,x+d-3,y+d-3,p);p.setColor(0xff101820);c.drawText(names[j],x+d*.35f,y+d*.65f,p);}}}}
}
